use super::*;
fn engine()->Engine {Engine::from_catalogue_bytes(include_bytes!(concat!(env!("OUT_DIR"),"/catalogue.json"))).unwrap()}
fn entry(code:&str)->Value {let c:Value=serde_json::from_slice(include_bytes!(concat!(env!("OUT_DIR"),"/catalogue.json"))).unwrap();c["cards"].as_array().unwrap().iter().find(|e|e["setCode"]==code).unwrap().clone()}
fn add(e:&Engine,s:&mut State,owner:Seat,code:&str)->CardId {let id=s.next_id;s.next_id+=1;*s.card_mut(id)=Card{present:true,def:e.by_code[code],owner,..Card::default()};id}
fn board(e:&Engine)->State {let mut s=State::default();s.hidden_history_exact=true;s.force_state_exact=true;for owner in [Seat::P1,Seat::P2]{let b=add(e,&mut s,owner,"SOR_023");let l=add(e,&mut s,owner,"SOR_014");s.player_mut(owner).base=b;s.player_mut(owner).leader=l;s.player_mut(owner).force_id=s.next_id;s.next_id+=1;}s}
fn unit(e:&Engine,s:&mut State,o:Seat,c:&str)->CardId {let id=add(e,s,o,c);e.add_arena(s,id).unwrap();id}
fn hand(e:&Engine,s:&mut State,o:Seat,c:&str)->CardId {let id=add(e,s,o,c);s.player_mut(o).hand.push(id).unwrap();id}
fn start(e:&Engine,s:&mut State,source:CardId,trigger:&str){s.source=source;s.active=s.card(source).owner;let p=e.card_programs(s,source).iter().copied().find(|p|e.program(*p).trigger==trigger).unwrap();e.begin_program(s,p,ProgramContinuation::Triggers).unwrap();}
fn click(e:&Engine,s:&mut State,id:CardId){*s=e.apply_ability_action(s,&e.card_action(s,id)).unwrap();}
#[test] fn captured_hand_cost_layout_context_hash_and_pending_import(){
 assert_eq!(std::mem::size_of::<State>(),39088);assert_eq!(std::mem::size_of::<ResolutionContext>(),112);
 let e=engine();let mut s=board(&e);let old=s.zobrist();let c=ResolutionContext::capture(&s);s.captured_hand_card=crate::captured_hand_cost_contract::PhysicalHandCard::capture(7).unwrap();assert_ne!(s.zobrist(),old);c.restore(&mut s);assert_eq!(s.zobrist(),old);
 s.captured_hand_card=crate::captured_hand_cost_contract::PhysicalHandCard::capture(7).unwrap();let frame=ResolutionContext::capture(&s);s.captured_hand_card=crate::captured_hand_cost_contract::PhysicalHandCard::capture(9).unwrap();frame.restore(&mut s);assert_eq!(s.captured_hand_card.id(),7);
 let source=unit(&e,&mut s,Seat::P1,"ASH_132");let selected=hand(&e,&mut s,Seat::P1,"ASH_190");s.captured_hand_card=Default::default();start(&e,&mut s,source,"whenPlayed");click(&e,&mut s,selected);let snap=e.snapshot(&s);assert_eq!(snap["capturedHandCostPending"],true);assert!(e.load_state(&snap).is_err());
}
#[test] fn captured_hand_cost_discard_higher_and_foreign_hand_both_seats(){let e=engine();for owner in [Seat::P1,Seat::P2]{let mut s=board(&e);let source=add(&e,&mut s,owner,"ASH_163");let chosen=hand(&e,&mut s,owner,"ASH_190");let foreign=hand(&e,&mut s,owner.other(),"ASH_131");let higher=unit(&e,&mut s,owner.other(),"ASH_131");let equal=unit(&e,&mut s,owner,"IBH_007");start(&e,&mut s,source,"event");assert_eq!(e.ability_actions(&s),vec![e.card_action(&s,chosen)]);click(&e,&mut s,chosen);assert_eq!(s.captured_hand_card.id(),chosen);assert!(s.player(owner).discard.contains(chosen));let actions=e.ability_actions(&s);assert!(actions.contains(&e.card_action(&s,higher)));assert!(!actions.contains(&e.card_action(&s,equal)));assert!(!actions.contains(&e.card_action(&s,foreign)));click(&e,&mut s,higher);assert_eq!(s.card(higher).damage,5);assert_eq!(s.captured_hand_card.id(),0);}}
#[test] fn captured_hand_cost_reveal_ack_equal_decline_both_hooks(){let e=engine();for owner in [Seat::P1,Seat::P2]{for trigger in ["whenPlayed","onAttack"]{let mut s=board(&e);let source=unit(&e,&mut s,owner,"ASH_132");let chosen=hand(&e,&mut s,owner,"ASH_190");hand(&e,&mut s,owner.other(),"ASH_131");let equal=unit(&e,&mut s,owner.other(),"IBH_007");let higher=unit(&e,&mut s,owner,"ASH_131");start(&e,&mut s,source,trigger);assert!(e.ability_actions(&s).contains(&Action::button("Choose nothing","done")));click(&e,&mut s,chosen);assert_eq!(s.active,owner.other());assert_eq!(e.ability_actions(&s),vec![Action::button("Done","done")]);assert!(s.player(owner).hand.contains(chosen));let copied=s;assert_eq!(copied.captured_hand_card.id(),chosen);s=e.apply_ability_action(&s,&Action::button("Done","done")).unwrap();assert_eq!(s.active,owner);assert!(e.ability_actions(&s).contains(&e.card_action(&s,equal)));assert!(!e.ability_actions(&s).contains(&e.card_action(&s,higher)));click(&e,&mut s,equal);assert_eq!(s.card(equal).damage,3);assert!(s.player(owner).hand.contains(chosen));assert_eq!(s.captured_hand_card.id(),0);
 start(&e,&mut s,source,trigger);s=e.apply_ability_action(&s,&Action::button("Choose nothing","done")).unwrap();assert_eq!(s.captured_hand_card.id(),0);
}}}
#[test] fn captured_hand_cost_closed_profiles_reject_shape_laundering_and_override_producers(){for id in ["ASH_163","ASH_132"]{let original=entry(id);assert!(crate::captured_hand_cost_contract::prepare(&original).unwrap().is_some());for path in ["/baseClass","/abilities/card/0/optional","/card/pilotBox","/keywordValues"]{let mut v=original.clone();let value=if path.ends_with("optional"){json!(true)}else{json!("bad")};if let Some(slot)=v.pointer_mut(path){*slot=value;}else{v["abilities"]["card"][0]["optional"]=value;}assert!(crate::captured_hand_cost_contract::prepare(&v).is_err(),"{id} {path}");}}
 let c=crate::ability_ir::Catalogue::load(&serde_json::from_slice::<Value>(include_bytes!(concat!(env!("OUT_DIR"),"/catalogue.json"))).unwrap()).unwrap();for id in ["LAW_036","LAW_126","LOF_056","TWI_116"]{assert!(!c.cards.contains_key(id),"printed override producer {id}");}
}
#[test] fn captured_hand_cost_physical_bounds_copy_frames_support_and_decline_import(){
 use crate::captured_hand_cost_contract::PhysicalHandCard;
 assert!(PhysicalHandCard::capture(0).is_err());assert!(PhysicalHandCard::capture(256).is_err());assert_eq!(PhysicalHandCard::capture(255).unwrap().id(),255);
 let e=engine();let mut s=board(&e);let source=unit(&e,&mut s,Seat::P1,"ASH_132");let selected=hand(&e,&mut s,Seat::P1,"ASH_190");start(&e,&mut s,source,"whenPlayed");click(&e,&mut s,selected);
 let saved=ResolutionContext::capture(&s);s.support.context=saved;s.death_frames[0].context=saved;s.death_depth=1;let baseline=s.zobrist();s.captured_hand_card=PhysicalHandCard::capture(1).unwrap();assert_ne!(s.zobrist(),baseline);s.support.context.restore(&mut s);assert_eq!(s.captured_hand_card.id(),selected);assert_eq!(s.zobrist(),baseline);
 let mut snap=e.snapshot(&s);snap.as_object_mut().unwrap().remove("capturedHandCostPending");snap.as_object_mut().unwrap().remove("viewSelectionPending");assert!(snap["actor"].is_null());assert!(e.load_state(&snap).is_err());
 s.death_depth=0;s.support=SupportState::default();s.decision=Decision::DeathPlayer;assert!(!e.hand_cost_prompt(&s));assert_eq!(e.ability_actions(&s),vec![Action::button("You",0),Action::button("Opponent",1)]);
}
#[test] fn captured_hand_cost_empty_own_hand_has_no_foreign_selection_or_continuation(){let e=engine();for owner in [Seat::P1,Seat::P2]{let mut s=board(&e);let source=add(&e,&mut s,owner,"ASH_163");hand(&e,&mut s,owner.other(),"ASH_190");hand(&e,&mut s,owner,"TWI_174");start(&e,&mut s,source,"event");assert_eq!(s.ability_program,0);assert_eq!(s.captured_hand_card.id(),0);}}
#[test] fn captured_hand_cost_raw_override_injection_rejected_before_metadata_drop(){
 let mut raw=entry("ASH_132");raw["abilities"]["card"][0]["untrusted"] = json!({"kind":"ongoingContract","effectType":"printedAttributesOverride"});let c=crate::ability_ir::Catalogue::load(&json!({"schema":crate::ability_ir::SCHEMA,"cards":[raw]})).unwrap();assert!(!c.cards.contains_key("ASH_132"));
 let e=engine();let mut pool=serde_json::from_slice::<Value>(include_bytes!(concat!(env!("OUT_DIR"),"/catalogue.json"))).unwrap();let approved=e.catalogue.as_ref().unwrap().metadata["SOR_023"].clone();pool=json!({"schema":"omni-rs-pool-v1","cards":[approved]});pool["cards"][0]["abilities"]=json!({"effectType":"printedAttributesOverride"});assert!(crate::validation::validate_pool(&pool).is_err());assert!(Engine::from_pool_value(&pool).is_err());assert!(Engine::from_compiled_pool_bytes(&serde_json::to_vec(&pool).unwrap(),include_bytes!(concat!(env!("OUT_DIR"),"/catalogue.json"))).is_err());
 let mut deep=Value::Null;for _ in 0..130 {deep=json!([deep]);}assert!(crate::captured_hand_cost_contract::reject_printed_override(&deep).is_err());
}
#[test] fn captured_hand_cost_reveal_empty_is_mandatory_skip(){let e=engine();let mut s=board(&e);let source=unit(&e,&mut s,Seat::P1,"ASH_132");hand(&e,&mut s,Seat::P2,"ASH_190");start(&e,&mut s,source,"whenPlayed");assert_eq!(e.ability_actions(&s),vec![Action::button("Skip","done")]);s=e.apply_ability_action(&s,&Action::button("Skip","done")).unwrap();assert_eq!(s.ability_program,0);}
#[test] fn captured_hand_cost_markers_cannot_hide_in_early_train_route(){for code in ["ASH_035","ASH_049"]{let mut v=entry(code);v["abilities"]["card"][0]["extra"]=json!({"kind":"reveal"});let c=crate::ability_ir::Catalogue::load(&json!({"schema":crate::ability_ir::SCHEMA,"cards":[v]})).unwrap();assert!(!c.cards.contains_key(code));}}
#[test] fn captured_hand_cost_closed_unknown_headers_and_metadata_reject(){for id in ["ASH_163","ASH_132"]{for field in ["unknownHeader","card","className"]{let mut e=entry(id);if field=="card"{e["card"]["unknownRules"]=json!({});}else{e[field]=json!(true);}assert!(crate::captured_hand_cost_contract::prepare(&e).is_err());}let mut renamed=entry(id);renamed["setCode"]=json!("TEST_999");assert!(crate::captured_hand_cost_contract::prepare(&renamed).unwrap().is_some());}}
#[test] fn captured_hand_cost_program_capacity_reserves_stored_program_plus_one(){let q=entry("ASH_132");let d=entry("ASH_163");assert!(crate::captured_hand_cost_contract::programs(&q,true,u16::MAX-1).is_err());assert!(crate::captured_hand_cost_contract::programs(&d,false,u16::MAX).is_err());assert!(crate::captured_hand_cost_contract::programs(&q,true,u16::MAX-2).is_ok());assert!(crate::captured_hand_cost_contract::programs(&d,false,u16::MAX-1).is_ok());}
#[test] fn captured_hand_cost_missing_unit_cost_is_scoped_to_reachable_selected_or_copied_graph(){
 let mut c:Value=serde_json::from_slice(include_bytes!(concat!(env!("OUT_DIR"),"/catalogue.json"))).unwrap();let bad=c["cards"].as_array_mut().unwrap().iter_mut().find(|e|e["setCode"]=="LOF_256").unwrap();bad["card"]["cost"]=Value::Null;
 assert!(Engine::from_catalogue_value(&c).err().unwrap().contains("WithCost"));
 let bytes=serde_json::to_vec(&c).unwrap();let raw_card=|id:&str|{let mut v=c["cards"].as_array().unwrap().iter().find(|e|e["setCode"]==id).unwrap()["card"].clone();v["setCode"]=json!(id);v};
 let plain=json!({"schema":"omni-rs-pool-v1","cards":[raw_card("TOKEN_SHIELD"),raw_card("SOR_023"),raw_card("SOR_014"),raw_card("LOF_256")]});let plain_bytes=serde_json::to_vec(&plain).unwrap();let e=Engine::from_compiled_pool_bytes(&plain_bytes,&bytes).unwrap();
 let mut relevant=plain.clone();relevant["cards"].as_array_mut().unwrap().push(raw_card("ASH_132"));assert!(Engine::from_compiled_pool_bytes(&serde_json::to_vec(&relevant).unwrap(),&bytes).err().unwrap().contains("WithCost"));
 let good=json!({"schema":"omni-rs-pool-v1","cards":[raw_card("TOKEN_SHIELD"),raw_card("SOR_023"),raw_card("SOR_014"),raw_card("ASH_132")]});assert!(Engine::from_compiled_pool_bytes(&serde_json::to_vec(&good).unwrap(),&bytes).is_ok());
 let mut state=board(&e);unit(&e,&mut state,Seat::P1,"LOF_256");let source=unit(&e,&mut state,Seat::P1,"ASH_132");assert!(e.validate_hand_cost_graph(Some(&state)).unwrap_err().contains("WithCost"));let before=state;state.source=source;assert!(e.apply(&state,&Action::button("Pass","pass")).is_err());assert_eq!(state.captured_hand_card,before.captured_hand_card);
}
